namespace SupplementStore_FinalProject
{
    /// <summary>
    /// Holds SQL statements for "Main Window"
    /// </summary>
    public class clsMainSQL
    {
        ////////////////////////////////////////////////////////////
        /// ALL FUNCTIONS WERE AUTOGENERATED AND MIGHT NOT WORK ////
        ////////////////////////////////////////////////////////////

        /// <summary>
        /// Selects all invoices ordered by invoice number
        /// </summary>
        public string SelectAllInvoices()
        {
            return "SELECT InvoiceNum, InvoiceDate, CustomerName, CustomerAddress " +
                   "FROM Invoices ORDER BY InvoiceNum";
        }

        /// <summary>
        /// Inserts new invoice
        /// </summary>
        public string InsertInvoice()
        {
            return "INSERT INTO Invoices " +
                   "(InvoiceNum, InvoiceDate, CustomerName, CustomerAddress) " +
                   "VALUES (?, ?, ?, ?)";
        }

        /// <summary>
        /// Updates invoice's date, customer name and address
        /// PK cannot be changed
        /// </summary>
        public string UpdateInvoice()
        {
            return "UPDATE Invoices SET InvoiceDate = ?, " +
                   "CustomerName = ?, CustomerAddress = ? WHERE InvoiceNum = ?";
        }

        /// <summary>
        /// Deletes invoice by invoice number
        /// </summary>
        public string DeleteInvoice()
        {
            return "DELETE FROM Invoices WHERE InvoiceNum = ?";
        }






    }
}